package com.villofarm.controller;
import com.villofarm.dto.AuthDtos.*;import com.villofarm.model.Role;import com.villofarm.model.UserEntity;import com.villofarm.repository.UserRepository;import com.villofarm.security.JwtService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}@PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@Valid @RequestBody RegisterRequest request){if(users.existsByEmailIgnoreCase(request.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");var user=new UserEntity();user.setName(request.name());user.setEmail(request.email().toLowerCase());user.setPassword(encoder.encode(request.password()));user.setRole(Role.USER);return response(users.save(user));}@PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest request){var user=users.findByEmailIgnoreCase(request.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(request.password(),user.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(user);}private AuthResponse response(UserEntity user){return new AuthResponse(jwt.create(user.getEmail()),new UserResponse(user.getId(),user.getName(),user.getEmail(),user.getRole()));}}
